const WARP = 9;

export const orb02Params = d.struct({
  anim: d.f32,
  inputVol: d.f32,
  mouse: d.vec2f,
  outputVol: d.f32,
  p_alphaGain: d.f32,
  p_baseVis: d.f32,
  p_bulge: d.f32,
  p_coreClamp: d.f32,
  p_falloff: d.f32,
  p_gain: d.f32,
  p_hueShift: d.f32,
  p_radius: d.f32,
  p_rim: d.f32,
  p_rimPow: d.f32,
  p_speed: d.f32,
  p_swell: d.f32,
  p_swirl: d.f32,
  p_warpFreq: d.f32,
  p_zoom: d.f32,
  res: d.vec2f,
  time: d.f32,
});

const layout = tgpu
  .bindGroupLayout({
    params: { uniform: orb02Params },
  })
  .$idx(0);

const rot2 = tgpu.fn(
  [d.f32],
  d.mat2x2f
)((angle) => {
  "use gpu";
  const c = std.cos(angle);
  const s = std.sin(angle);
  return d.mat2x2f(d.vec2f(c, -s), d.vec2f(s, c));
});

const tanh3 = tgpu.fn(
  [d.vec3f],
  d.vec3f
)((x) => {
  "use gpu";
  const clamped = std.clamp(x, d.vec3f(-10), d.vec3f(10));
  const e = std.exp(clamped.mul(2));
  return e.sub(1).div(e.add(1));
