    const sw = animTime * u.p_swirl;
    p = std.mul(rot2(sw), p);

    const warpFreq = u.p_warpFreq * (1 + 0.35 * u.inputVol);
    const gain = u.p_gain * (0.75 + 0.7 * u.outputVol);

    let acc = d.vec4f();
