const STEPS = 80;
const TURB = 8;

export const orb03Params = d.struct({
  anim: d.f32,
  c_tint: d.vec3f,
  inputVol: d.f32,
  mouse: d.vec2f,
  outputVol: d.f32,
  p_alphaGain: d.f32,
  p_camDist: d.f32,
  p_contrast: d.f32,
  p_edge: d.f32,
  p_edgeFade: d.f32,
  p_envCore: d.f32,
  p_envRadius: d.f32,
  p_exposure: d.f32,
  p_feedback: d.f32,
  p_fill: d.f32,
  p_focal: d.f32,
  p_hue: d.f32,
  p_plane: d.f32,
  p_pulse: d.f32,
  p_saturation: d.f32,
  p_scatter: d.f32,
  p_shellR: d.f32,
  p_shellW: d.f32,
  p_speed: d.f32,
  p_spread: d.f32,
  p_stepClamp: d.f32,
  p_surge: d.f32,
  p_turb: d.f32,
  p_wander: d.f32,
  p_width: d.f32,
  res: d.vec2f,
  time: d.f32,
});

const layout = tgpu
  .bindGroupLayout({
    params: { uniform: orb03Params },
  })
  .$idx(0);

const tanh3 = tgpu.fn(
  [d.vec3f],
  d.vec3f
)((x) => {
  "use gpu";
  const clamped = std.clamp(x, d.vec3f(-10), d.vec3f(10));
  const e = std.exp(clamped.mul(2));
  return e.sub(1).div(e.add(1));
