  p_flow: d.f32,
  p_gain: d.f32,
  p_iris: d.f32,
  p_irisScale: d.f32,
  p_light: d.f32,
  p_radius: d.f32,
  p_rim: d.f32,
  p_scale: d.f32,
  p_speed: d.f32,
  p_split: d.f32,
  p_swirl: d.f32,
  p_thick: d.f32,
  p_view: d.f32,
  p_warp: d.f32,
