export const orb11Params = d.struct({
  anim: d.f32,
  inputVol: d.f32,
  mouse: d.vec2f,
  outputVol: d.f32,
  p_baseVis: d.f32,
  p_chromaSpread: d.f32,
  p_flowAmp: d.f32,
  p_flowScale: d.f32,
  p_flowSpeed: d.f32,
  p_glow: d.f32,
  p_metalDark: d.f32,
  p_posScale: d.f32,
  p_precess: d.f32,
  p_probGain: d.f32,
  p_probPow: d.f32,
  p_radialDecay: d.f32,
  p_radialPow: d.f32,
  p_radius: d.f32,
  p_rotSpeed: d.f32,
  p_speed: d.f32,
  p_swell: d.f32,
  p_waveFreq: d.f32,
  res: d.vec2f,
  time: d.f32,
});

const layout = tgpu
  .bindGroupLayout({
    params: { uniform: orb11Params },
  })
  .$idx(0);

const hash = tgpu.fn(
  [d.vec2f],
  d.f32
)((p) =>
  std.fract(std.sin(std.dot(p, d.vec2f(127.1, 311.7))) * 43_758.545_312_3)
);

const noise = tgpu.fn(
  [d.vec2f],
  d.f32
)((p) => {
  "use gpu";
  const i = std.floor(p);
  const f = std.fract(p);
  const ff = f.mul(f).mul(d.vec2f(3).sub(f.mul(2)));
  return std.mix(
    std.mix(hash(i), hash(i.add(d.vec2f(1, 0))), ff.x),
    std.mix(hash(i.add(d.vec2f(0, 1))), hash(i.add(d.vec2f(1, 1))), ff.x),
    ff.y
  );
});

const fbm = tgpu.fn(
  [d.vec2f],
  d.f32
)((pIn) => {
  "use gpu";
  let p = d.vec2f(pIn);
  let v = d.f32(0);
  let a = d.f32(0.5);
  for (const _i of std.range(5)) {
    v += a * noise(p);
    p = p.mul(2.03).add(d.vec2f(11.7, 7.3));
    a *= 0.5;
  }
