export { meta, orb15Orb } from "@/components/orbs/orb-15/meta";

export type Orb15Props = Omit<ShaderOrbProps, "variant">;

export const Orb15 = ({ size = 280, ...rest }: Orb15Props) => (
  <ShaderOrb variant={orb15Orb} size={size} {...rest} />
