  anim: d.f32,
  c_deep: d.vec3f,
  c_flash: d.vec3f,
  c_hot: d.vec3f,
  c_low: d.vec3f,
  c_mid: d.vec3f,
  inputVol: d.f32,
  mouse: d.vec2f,
  outputVol: d.f32,
  p_bands: d.f32,
  p_churn: d.f32,
  p_contrast: d.f32,
  p_filmGrain: d.f32,
  p_flash: d.f32,
  p_flashRate: d.f32,
  p_gain: d.f32,
  p_grain: d.f32,
  p_grainSize: d.f32,
  p_light: d.f32,
  p_radius: d.f32,
  p_rainbow: d.f32,
  p_rim: d.f32,
  p_scale: d.f32,
  p_shear: d.f32,
  p_speed: d.f32,
  p_spin: d.f32,
  p_warp: d.f32,
  res: d.vec2f,
  time: d.f32,
});

const layout = tgpu
  .bindGroupLayout({
    params: { uniform: orb17Params },
  })
  .$idx(0);

const hash = tgpu.fn(
  [d.vec2f],
  d.f32
)((p) =>
  std.fract(std.sin(std.dot(p, d.vec2f(127.1, 311.7))) * 43_758.545_312_3)
);

const noise = tgpu.fn(
  [d.vec2f],
  d.f32
)((p) => {
  "use gpu";
  const i = std.floor(p);
  const f = std.fract(p);
  const ff = f.mul(f).mul(d.vec2f(3).sub(f.mul(2)));
  return std.mix(
    std.mix(hash(i), hash(i.add(d.vec2f(1, 0))), ff.x),
    std.mix(hash(i.add(d.vec2f(0, 1))), hash(i.add(d.vec2f(1, 1))), ff.x),
    ff.y
  );
});

const fbm = tgpu.fn(
  [d.vec2f],
  d.f32
)((pIn) => {
  "use gpu";
  let p = d.vec2f(pIn);
  let v = d.f32(0);
  let a = d.f32(0.5);
