    const g2 = grainNoise(gpix, frame, 27.9);
    col = col.mul(1 + (g2 - 0.5) * u.p_filmGrain);

    const alpha = mask;
    return d.vec4f(std.max(col, d.vec3f()).mul(alpha), alpha);
  })
