  outputVol: d.f32,
  p_bead: d.f32,
  p_bulge: d.f32,
  p_contrast: d.f32,
  p_edge: d.f32,
  p_floorLevel: d.f32,
  p_gain: d.f32,
  p_grow: d.f32,
  p_jitter: d.f32,
  p_light: d.f32,
  p_radius: d.f32,
  p_rim: d.f32,
  p_saturation: d.f32,
  p_scale: d.f32,
  p_skew: d.f32,
  p_slide: d.f32,
  p_speed: d.f32,
  p_swirl: d.f32,
  p_vary: d.f32,
