  anim: d.f32,
  c_tint: d.vec3f,
  inputVol: d.f32,
  mouse: d.vec2f,
  outputVol: d.f32,
  p_alphaGain: d.f32,
  p_camDist: d.f32,
  p_contrast: d.f32,
  p_edge: d.f32,
  p_edgeFade: d.f32,
  p_envCore: d.f32,
  p_envRadius: d.f32,
  p_exposure: d.f32,
  p_fill: d.f32,
  p_focal: d.f32,
  p_glow: d.f32,
  p_glowFew: d.f32,
  p_hueDepth: d.f32,
  p_hueStep: d.f32,
  p_hug: d.f32,
  p_saturation: d.f32,
  p_scatter: d.f32,
  p_speed: d.f32,
  p_stepClamp: d.f32,
  p_stepScale: d.f32,
  p_turb: d.f32,
  p_wander: d.f32,
  res: d.vec2f,
  time: d.f32,
});

