export { meta, orb25Orb } from "@/components/orbs/orb-25/meta";

export type Orb25Props = Omit<ShaderOrbProps, "variant">;

export const Orb25 = ({ size = 280, ...rest }: Orb25Props) => (
  <ShaderOrb variant={orb25Orb} size={size} {...rest} />
