import type { ShaderOrbProps } from "@/components/orbs/canvas";
import { ShaderOrb } from "@/components/orbs/canvas";
import { orb26Orb } from "@/components/orbs/orb-26/meta";

export { meta, orb26Orb } from "@/components/orbs/orb-26/meta";

