const FBM3_OCT = 4;

export const orb27Params = d.struct({
  anim: d.f32,
  c_c0: d.vec3f,
  c_c1: d.vec3f,
  c_c2: d.vec3f,
  c_c3: d.vec3f,
  c_c4: d.vec3f,
  c_c5: d.vec3f,
  c_c6: d.vec3f,
  c_paper: d.vec3f,
  inputVol: d.f32,
  mouse: d.vec2f,
  outputVol: d.f32,
  p_cells: d.f32,
  p_curve: d.f32,
  p_density: d.f32,
  p_dither: d.f32,
  p_dot: d.f32,
  p_freq: d.f32,
  p_grain: d.f32,
  p_hi: d.f32,
  p_light: d.f32,
  p_lo: d.f32,
  p_radius: d.f32,
  p_rim: d.f32,
  p_scale: d.f32,
  p_sparse: d.f32,
  p_speed: d.f32,
  p_spin: d.f32,
  p_swirl: d.f32,
  p_twinkle: d.f32,
  p_vortex: d.f32,
  p_warp: d.f32,
  res: d.vec2f,
  time: d.f32,
