  "use gpu";
  const eps = 0.001;
  const normal = std.mul(
    globalInvRot,
    std.normalize(
      d.vec3f(
        coronaSDF(
          p.add(d.vec3f(eps, 0, 0)),
          shellRadius,
          warpAmount,
          warpFreqNow,
          smoothKNow
