const STEPS = 56;
const TURB_OCT = 4;

export const orb32Params = d.struct({
  anim: d.f32,
  c_core: d.vec3f,
  c_deep: d.vec3f,
  c_inner: d.vec3f,
  c_outer: d.vec3f,
  c_rim: d.vec3f,
  c_tint: d.vec3f,
  inputVol: d.f32,
  mouse: d.vec2f,
  outputVol: d.f32,
  p_absorb: d.f32,
  p_alphaGain: d.f32,
  p_armSharp: d.f32,
  p_arms: d.f32,
  p_beat: d.f32,
  p_breathe: d.f32,
  p_bulge: d.f32,
  p_camDist: d.f32,
  p_churn: d.f32,
  p_contrast: d.f32,
  p_core: d.f32,
  p_density: d.f32,
  p_edge: d.f32,
  p_edgeFade: d.f32,
  p_envRadius: d.f32,
  p_exposure: d.f32,
  p_falloff: d.f32,
  p_fill: d.f32,
  p_focal: d.f32,
  p_hueReach: d.f32,
  p_pulse: d.f32,
  p_ragged: d.f32,
  p_rim: d.f32,
  p_saturation: d.f32,
  p_spin: d.f32,
  p_starDensity: d.f32,
  p_starScale: d.f32,
  p_stars: d.f32,
  p_thick: d.f32,
  p_threshold: d.f32,
  p_tilt: d.f32,
  p_turbScale: d.f32,
